class RideSharingSystem {
  private final java.util.ArrayDeque<Integer> riders = new java.util.ArrayDeque<>();
  private final java.util.ArrayDeque<Integer> drivers = new java.util.ArrayDeque<>();
  private final java.util.HashSet<Integer> waiting = new java.util.HashSet<>();

  public RideSharingSystem() {}

  public void addRider(int riderId) {
    riders.add(riderId);
    waiting.add(riderId);
  }

  public void addDriver(int driverId) {
    drivers.add(driverId);
  }

  public int[] matchDriverWithRider() {
    while (!riders.isEmpty() && !waiting.contains(riders.peek())) riders.poll();
    if (riders.isEmpty() || drivers.isEmpty()) return new int[] {-1, -1};
    int rider = riders.poll();
    waiting.remove(rider);
    return new int[] {drivers.poll(), rider};
  }

  public void cancelRider(int riderId) {
    waiting.remove(riderId);
  }
}
